{
  "name": "USB4000光谱仪",
  "name_en": "USB4000 Spectrometer",
  "manufacturer": "Ocean Optics",
  "description": "Ocean Optics USB4000 是一款通过 USB 控制的实验室光谱仪，可设置积分时间、配置触发方式、采集光谱，并查询温度、固件版本和设备状态，常用于光谱测量与光学表征。",
  "description_en": "The Ocean Optics USB4000 is a USB-controlled laboratory spectrometer used to set integration time, configure trigger modes, acquire spectra, and query temperature, firmware version, and device status for spectroscopy and optical characterization.",
  "tag_hints": [
    "spectroscopy",
    "USB spectrometer",
    "optical detection",
    "integration time control",
    "triggered acquisition",
    "Ocean Optics"
  ],
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化光谱仪并建立内部通信参数。",
      "description_en": "Initialize the spectrometer and set up internal communication parameters."
    },
    {
      "action_name": "auto-integration_time",
      "description": "设置光谱采集的积分时间（微秒）。",
      "description_en": "Set the spectrometer integration time for acquisitions in microseconds."
    },
    {
      "action_name": "auto-query_config",
      "description": "查询光谱仪指定配置位置或寄存器中的值。",
      "description_en": "Query the value stored at a specified spectrometer configuration position or register."
    },
    {
      "action_name": "auto-reset",
      "description": "重置光谱仪。",
      "description_en": "Reset the spectrometer."
    },
    {
      "action_name": "auto-pcb_temperature",
      "description": "读取仪器电路板温度。",
      "description_en": "Read the instrument PCB temperature."
    },
    {
      "action_name": "auto-firmware_version",
      "description": "读取光谱仪固件版本。",
      "description_en": "Read the spectrometer firmware version."
    },
    {
      "action_name": "auto-trigger",
      "description": "设置光谱采集的触发模式。",
      "description_en": "Set the trigger mode for spectral acquisition."
    },
    {
      "action_name": "auto-request_spectra",
      "description": "请求采集并返回光谱数据。",
      "description_en": "Request an acquisition and return spectral data."
    },
    {
      "action_name": "auto-get_status",
      "description": "获取设备状态信息。",
      "description_en": "Get device status information."
    }
  ]
}

